import type { Metadata } from "next";
import { Geist, Geist_Mono } from "next/font/google";
import "./globals.css";
import Navigation from "@/components/Navigation";
import Footer from "@/components/Footer";

const geistSans = Geist({
  variable: "--font-geist-sans",
  subsets: ["latin"],
});

const geistMono = Geist_Mono({
  variable: "--font-geist-mono",
  subsets: ["latin"],
});

export const metadata: Metadata = {
  metadataBase: new URL('https://luxeinteriors.com'),
  title: {
    default: "Luxe Interiors - Ultra-Premium Interior Design in India",
    template: "%s | Luxe Interiors"
  },
  description: "India's premier luxury interior design firm. Crafting timeless spaces that elevate daily life for discerning clients across Mumbai, Bangalore, Delhi, and beyond.",
  keywords: ["luxury interior design India", "premium interiors Mumbai", "luxury home design Bangalore", "bespoke interiors Delhi", "high-end interior designer", "luxury villa design", "commercial interior design"],
  authors: [{ name: "Luxe Interiors" }],
  openGraph: {
    type: "website",
    locale: "en_IN",
    url: "https://luxeinteriors.com",
    siteName: "Luxe Interiors",
    title: "Luxe Interiors - Ultra-Premium Interior Design in India",
    description: "India's premier luxury interior design firm crafting timeless spaces.",
  },
  twitter: {
    card: "summary_large_image",
    title: "Luxe Interiors - Ultra-Premium Interior Design",
    description: "India's premier luxury interior design firm crafting timeless spaces.",
  },
  robots: {
    index: true,
    follow: true,
  },
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="en">
      <head>
        <link rel="preconnect" href="https://fonts.googleapis.com" />
        <link rel="preconnect" href="https://fonts.gstatic.com" crossOrigin="anonymous" />
        <link 
          href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@300;400;500;600;700&family=Lato:wght@300;400;700&display=swap" 
          rel="stylesheet" 
        />
      </head>
      <body className="antialiased">
        <Navigation />
        <main>{children}</main>
        <Footer />
      </body>
    </html>
  );
}

'use client';

import { notFound } from 'next/navigation';
import { motion } from 'framer-motion';
import { useState } from 'react';
import Link from 'next/link';
import Container from '@/components/ui/Container';
import Button from '@/components/ui/Button';
import { projects } from '@/lib/projectsData';

function ProjectDetailPage({ params }: { params: { slug: string } }) {
  const project = projects.find(p => p.slug === params.slug);
  const [selectedImageIndex, setSelectedImageIndex] = useState(0);

  if (!project) {
    notFound();
  }

  const relatedProjects = projects
    .filter(p => p.id !== project.id && (p.category === project.category || p.city === project.city))
    .slice(0, 3);

  return (
    <div className="pt-24 pb-24 bg-[#FFFFF0] min-h-screen">
      <Container>
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
          className="mb-8"
        >
          <Link href="/portfolio" className="inline-flex items-center text-[#36454F]/70 hover:text-[#D4AF37] transition-colors mb-6">
            <svg className="w-5 h-5 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
            </svg>
            Back to Portfolio
          </Link>

          <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4 mb-6">
            <div>
              <div className="flex items-center gap-3 mb-3">
                <span className="bg-[#D4AF37] text-white px-3 py-1 text-xs font-semibold uppercase tracking-wider">
                  {project.category}
                </span>
                {project.featured && (
                  <span className="bg-[#0A1628] text-white px-3 py-1 text-xs font-semibold uppercase tracking-wider">
                    Featured
                  </span>
                )}
              </div>
              <h1 className="text-4xl md:text-5xl lg:text-6xl font-display font-semibold text-[#0A1628] mb-3">
                {project.title}
              </h1>
              <p className="text-xl text-[#36454F]/80">{project.location}, {project.city}</p>
            </div>
            <Button variant="secondary">Book Consultation</Button>
          </div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6, delay: 0.2 }}
          className="mb-12"
        >
          <div className="relative aspect-[16/9] mb-6 rounded-sm overflow-hidden">
            <img
              src={project.images[selectedImageIndex]}
              alt={`${project.title} - Image ${selectedImageIndex + 1}`}
              className="w-full h-full object-cover"
            />
          </div>

          {project.images.length > 1 && (
            <div className="grid grid-cols-4 md:grid-cols-6 lg:grid-cols-8 gap-4">
              {project.images.map((image, index) => (
                <button
                  key={index}
                  onClick={() => setSelectedImageIndex(index)}
                  className={`aspect-square rounded-sm overflow-hidden border-2 transition-all ${selectedImageIndex === index
                    ? 'border-[#D4AF37] scale-95'
                    : 'border-transparent hover:border-[#E8E8E8]'
                    }`}
                >
                  <img src={image} alt={`Thumbnail ${index + 1}`} className="w-full h-full object-cover" />
                </button>
              ))}
            </div>
          )}
        </motion.div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-12 mb-16">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, delay: 0.3 }}
            className="lg:col-span-2 space-y-8"
          >
            <div>
              <h2 className="text-3xl font-display font-semibold text-[#0A1628] mb-4">
                Project Overview
              </h2>
              <p className="text-lg text-[#36454F]/80 leading-relaxed">
                {project.description}
              </p>
            </div>

            {project.clientBrief && (
              <div className="bg-white p-6 rounded-sm border border-[#E8E8E8]">
                <h3 className="text-xl font-display font-semibold text-[#0A1628] mb-3">
                  Client Brief
                </h3>
                <p className="text-[#36454F]/80 leading-relaxed">
                  {project.clientBrief}
                </p>
              </div>
            )}

            {project.designApproach && (
              <div>
                <h3 className="text-2xl font-display font-semibold text-[#0A1628] mb-4">
                  Design Approach
                </h3>
                <p className="text-[#36454F]/80 leading-relaxed">
                  {project.designApproach}
                </p>
              </div>
            )}

            {project.keyFeatures && project.keyFeatures.length > 0 && (
              <div>
                <h3 className="text-2xl font-display font-semibold text-[#0A1628] mb-4">
                  Key Features
                </h3>
                <ul className="space-y-3">
                  {project.keyFeatures.map((feature, index) => (
                    <li key={index} className="flex items-start">
                      <span className="text-[#D4AF37] mr-3 mt-1">Γ£ª</span>
                      <span className="text-[#36454F]/80">{feature}</span>
                    </li>
                  ))}
                </ul>
              </div>
            )}

            {project.testimonial && (
              <div className="bg-[#0A1628] text-[#FFFFF0] p-8 rounded-sm">
                <blockquote className="text-xl font-light italic mb-4 leading-relaxed">
                  &ldquo;{project.testimonial.quote}&rdquo;
                </blockquote>
                <p className="text-[#D4AF37] font-semibold">
                  ΓÇö {project.testimonial.client}
                </p>
              </div>
            )}
          </motion.div>

          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, delay: 0.4 }}
            className="space-y-6"
          >
            <div className="bg-white p-6 rounded-sm border border-[#E8E8E8] sticky top-32">
              <h3 className="text-xl font-display font-semibold text-[#0A1628] mb-6">
                Project Details
              </h3>
              <div className="space-y-4">
                <div className="pb-4 border-b border-[#E8E8E8]">
                  <p className="text-sm text-[#36454F]/60 mb-1 uppercase tracking-wider">Location</p>
                  <p className="text-[#0A1628] font-medium">{project.location}, {project.city}</p>
                </div>
                <div className="pb-4 border-b border-[#E8E8E8]">
                  <p className="text-sm text-[#36454F]/60 mb-1 uppercase tracking-wider">Year</p>
                  <p className="text-[#0A1628] font-medium">{project.year}</p>
                </div>
                <div className="pb-4 border-b border-[#E8E8E8]">
                  <p className="text-sm text-[#36454F]/60 mb-1 uppercase tracking-wider">Square Feet</p>
                  <p className="text-[#0A1628] font-medium">{project.squareFeet.toLocaleString()}</p>
                </div>
                <div className="pb-4 border-b border-[#E8E8E8]">
                  <p className="text-sm text-[#36454F]/60 mb-1 uppercase tracking-wider">Timeline</p>
                  <p className="text-[#0A1628] font-medium">{project.timeline}</p>
                </div>
                <div className="pb-4 border-b border-[#E8E8E8]">
                  <p className="text-sm text-[#36454F]/60 mb-1 uppercase tracking-wider">Style</p>
                  <div className="flex flex-wrap gap-2 mt-2">
                    {project.style.map((s) => (
                      <span key={s} className="bg-[#FFFFF0] text-[#36454F] px-3 py-1 text-xs rounded-full">
                        {s}
                      </span>
                    ))}
                  </div>
                </div>
                <div>
                  <p className="text-sm text-[#36454F]/60 mb-1 uppercase tracking-wider">Space Type</p>
                  <p className="text-[#0A1628] font-medium">{project.spaceType}</p>
                </div>
              </div>

              <div className="mt-8">
                <Button className="w-full" variant="primary">
                  Start Your Project
                </Button>
              </div>
            </div>
          </motion.div>
        </div>

        {relatedProjects.length > 0 && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, delay: 0.5 }}
            className="border-t border-[#E8E8E8] pt-16"
          >
            <h2 className="text-3xl font-display font-semibold text-[#0A1628] mb-8">
              Related Projects
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
              {relatedProjects.map((related) => (
                <Link key={related.id} href={`/portfolio/${related.slug}`}>
                  <div className="group cursor-pointer">
                    <div className="relative aspect-[4/3] mb-4 rounded-sm overflow-hidden">
                      <img
                        src={related.image}
                        alt={related.title}
                        className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110"
                      />
                    </div>
                    <h3 className="text-xl font-display font-semibold text-[#0A1628] mb-2 group-hover:text-[#D4AF37] transition-colors">
                      {related.title}
                    </h3>
                    <p className="text-[#36454F]/70 text-sm">{related.city}</p>
                  </div>
                </Link>
              ))}
            </div>
          </motion.div>
        )}
      </Container>
    </div>
  );
}

export default ProjectDetailPage;

'use client';

import { useState, useMemo, useRef } from 'react';
import { motion, useInView } from 'framer-motion';
import Link from 'next/link';
import Container from '@/components/ui/Container';
import Card from '@/components/ui/Card';
import Button from '@/components/ui/Button';
import { projects, categories, cities, styles, spaceTypes } from '@/lib/projectsData';

function PortfolioPage() {
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [selectedCity, setSelectedCity] = useState('All');
  const [selectedStyle, setSelectedStyle] = useState('All');
  const [selectedSpaceType, setSelectedSpaceType] = useState('All');
  const [searchQuery, setSearchQuery] = useState('');

  const filtersRef = useRef(null);
  const gridRef = useRef(null);
  const ctaRef = useRef(null);
  const filtersInView = useInView(filtersRef, { once: true, margin: '0px' });
  const gridInView = useInView(gridRef, { once: true, margin: '0px' });
  const ctaInView = useInView(ctaRef, { once: true, margin: '0px' });

  const filteredProjects = useMemo(() => {
    return projects.filter((project) => {
      const matchesCategory = selectedCategory === 'All' || project.category === selectedCategory;
      const matchesCity = selectedCity === 'All' || project.city === selectedCity;
      const matchesStyle = selectedStyle === 'All' || project.style.includes(selectedStyle);
      const matchesSpaceType = selectedSpaceType === 'All' || project.spaceType === selectedSpaceType;
      const matchesSearch = searchQuery === '' ||
        project.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
        project.description.toLowerCase().includes(searchQuery.toLowerCase()) ||
        project.location.toLowerCase().includes(searchQuery.toLowerCase());

      return matchesCategory && matchesCity && matchesStyle && matchesSpaceType && matchesSearch;
    });
  }, [selectedCategory, selectedCity, selectedStyle, selectedSpaceType, searchQuery]);

  const resetFilters = () => {
    setSelectedCategory('All');
    setSelectedCity('All');
    setSelectedStyle('All');
    setSelectedSpaceType('All');
    setSearchQuery('');
  };

  return (
    <div className="min-h-screen bg-off-white">
      {/* Dramatic Asymmetric Header with Split Layout */}
      <section className="pt-32 pb-24 bg-cream relative overflow-hidden">
        <div className="max-w-[1600px] mx-auto px-6 md:px-12">
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
            {/* Left Content - 7 columns */}
            <div className="lg:col-span-7">
              <motion.div
                initial={{ opacity: 0, x: -40 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ duration: 0.8, ease: "easeOut" }}
              >
                <span className="text-rose-gold text-xs font-bold uppercase tracking-[0.3em] mb-8 block">
                  Our Work
                </span>
                <h1 className="text-5xl md:text-6xl lg:text-7xl xl:text-8xl font-display font-semibold text-deep-charcoal leading-[0.9] mb-10">
                  Portfolio of
                  <br />
                  <span className="text-rose-gold">Excellence</span>
                </h1>
                <div className="w-24 h-[3px] bg-gradient-to-r from-rose-gold to-rose-gold/30 mb-8" />
                <p className="text-base lg:text-lg text-charcoal leading-relaxed max-w-xl mb-12">
                  Explore our collection of luxury transformations across India&apos;s most prestigious addresses. Each project tells a unique story of craftsmanship and refined elegance.
                </p>
                <div className="flex flex-wrap gap-6">
                  <div className="text-center">
                    <div className="text-4xl lg:text-5xl font-display font-bold text-rose-gold mb-2">{projects.length}+</div>
                    <p className="text-xs text-warm-gray uppercase tracking-wider">Projects</p>
                  </div>
                  <div className="w-[1px] bg-soft-gray" />
                  <div className="text-center">
                    <div className="text-4xl lg:text-5xl font-display font-bold text-rose-gold mb-2">12+</div>
                    <p className="text-xs text-warm-gray uppercase tracking-wider">Cities</p>
                  </div>
                  <div className="w-[1px] bg-soft-gray" />
                  <div className="text-center">
                    <div className="text-4xl lg:text-5xl font-display font-bold text-rose-gold mb-2">15+</div>
                    <p className="text-xs text-warm-gray uppercase tracking-wider">Years</p>
                  </div>
                </div>
              </motion.div>
            </div>

            {/* Right Stats Panel - 5 columns */}
            <div className="lg:col-span-5 relative">
              <motion.div
                initial={{ opacity: 0, x: 40 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ duration: 0.8, delay: 0.3 }}
                className="bg-deep-charcoal p-10 lg:p-14 h-full flex flex-col justify-between relative overflow-hidden group"
              >
                <div className="absolute top-0 right-0 w-32 h-32 bg-rose-gold/10 transition-all duration-700 group-hover:bg-rose-gold/20 group-hover:scale-110" />
                <div className="relative z-10">
                  <span className="text-rose-gold text-xs font-bold uppercase tracking-wider mb-6 block">Project Categories</span>
                  <div className="space-y-6">
                    <div className="flex items-center justify-between py-4 border-b border-white/10">
                      <span className="text-white font-medium">Residential</span>
                      <span className="text-rose-gold font-display text-2xl font-bold">{projects.filter(p => p.category === 'Residential').length}</span>
                    </div>
                    <div className="flex items-center justify-between py-4 border-b border-white/10">
                      <span className="text-white font-medium">Commercial</span>
                      <span className="text-rose-gold font-display text-2xl font-bold">{projects.filter(p => p.category === 'Commercial').length}</span>
                    </div>
                    <div className="flex items-center justify-between py-4 border-b border-white/10">
                      <span className="text-white font-medium">Hospitality</span>
                      <span className="text-rose-gold font-display text-2xl font-bold">{projects.filter(p => p.category === 'Hospitality').length}</span>
                    </div>
                    <div className="flex items-center justify-between py-4 border-b border-white/10">
                      <span className="text-white font-medium">All Projects</span>
                      <span className="text-rose-gold font-display text-2xl font-bold">{projects.length}</span>
                    </div>
                  </div>
                </div>
                <div className="mt-8 pt-6 border-t border-white/20">
                  <p className="text-white/70 text-sm leading-relaxed">From contemporary penthouses to heritage restorations, our portfolio showcases versatility and excellence.</p>
                </div>
              </motion.div>
            </div>
          </div>
        </div>
      </section>

      {/* Modern Editorial Filter Panel */}
      <section ref={filtersRef} className="py-16 bg-off-white relative overflow-hidden">
        <Container>
          <motion.div
            initial={{ opacity: 0, y: 30 }}
            animate={filtersInView ? { opacity: 1, y: 0 } : {}}
            transition={{ duration: 0.8 }}
            className="relative"
          >
            <div className="bg-white shadow-xl hover:shadow-2xl transition-shadow duration-500 relative overflow-hidden group">
              <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-rose-gold via-rose-gold/50 to-transparent" />
              <div className="p-8 lg:p-12">
                <div className="flex items-center justify-between mb-8">
                  <div>
                    <h2 className="text-2xl lg:text-3xl font-display font-semibold text-deep-charcoal mb-2">Explore Projects</h2>
                    <p className="text-sm text-warm-gray">Filter by your preferences to find the perfect inspiration</p>
                  </div>
                  <button
                    onClick={resetFilters}
                    className="px-6 py-3 bg-cream text-rose-gold hover:bg-rose-gold hover:text-white font-semibold text-sm uppercase tracking-wider transition-all duration-300"
                  >
                    Reset All
                  </button>
                </div>

                {/* Search Bar */}
                <div className="mb-8 relative group">
                  <input
                    type="text"
                    placeholder="Search by project name, location, or description..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="w-full px-6 py-4 bg-off-white border-2 border-transparent focus:border-rose-gold focus:bg-white transition-all duration-300 text-deep-charcoal placeholder:text-warm-gray"
                  />
                  <svg className="absolute right-6 top-1/2 -translate-y-1/2 w-5 h-5 text-rose-gold" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                  </svg>
                </div>

                {/* Filter Grid */}
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
                  <div className="relative group">
                    <label className="block text-xs font-bold text-rose-gold mb-3 uppercase tracking-wider">
                      Category
                    </label>
                    <select
                      value={selectedCategory}
                      onChange={(e) => setSelectedCategory(e.target.value)}
                      className="w-full px-5 py-3 bg-cream border-2 border-transparent hover:border-rose-gold focus:border-rose-gold focus:bg-white transition-all duration-300 appearance-none cursor-pointer"
                    >
                      {categories.map((cat) => (
                        <option key={cat} value={cat}>{cat}</option>
                      ))}
                    </select>
                    <svg className="absolute right-4 top-[42px] w-4 h-4 text-rose-gold pointer-events-none" fill="currentColor" viewBox="0 0 20 20">
                      <path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" />
                    </svg>
                  </div>

                  <div className="relative group">
                    <label className="block text-xs font-bold text-rose-gold mb-3 uppercase tracking-wider">
                      City
                    </label>
                    <select
                      value={selectedCity}
                      onChange={(e) => setSelectedCity(e.target.value)}
                      className="w-full px-5 py-3 bg-cream border-2 border-transparent hover:border-rose-gold focus:border-rose-gold focus:bg-white transition-all duration-300 appearance-none cursor-pointer"
                    >
                      {cities.map((city) => (
                        <option key={city} value={city}>{city}</option>
                      ))}
                    </select>
                    <svg className="absolute right-4 top-[42px] w-4 h-4 text-rose-gold pointer-events-none" fill="currentColor" viewBox="0 0 20 20">
                      <path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" />
                    </svg>
                  </div>

                  <div className="relative group">
                    <label className="block text-xs font-bold text-rose-gold mb-3 uppercase tracking-wider">
                      Design Style
                    </label>
                    <select
                      value={selectedStyle}
                      onChange={(e) => setSelectedStyle(e.target.value)}
                      className="w-full px-5 py-3 bg-cream border-2 border-transparent hover:border-rose-gold focus:border-rose-gold focus:bg-white transition-all duration-300 appearance-none cursor-pointer"
                    >
                      {styles.map((style) => (
                        <option key={style} value={style}>{style}</option>
                      ))}
                    </select>
                    <svg className="absolute right-4 top-[42px] w-4 h-4 text-rose-gold pointer-events-none" fill="currentColor" viewBox="0 0 20 20">
                      <path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" />
                    </svg>
                  </div>

                  <div className="relative group">
                    <label className="block text-xs font-bold text-rose-gold mb-3 uppercase tracking-wider">
                      Space Type
                    </label>
                    <select
                      value={selectedSpaceType}
                      onChange={(e) => setSelectedSpaceType(e.target.value)}
                      className="w-full px-5 py-3 bg-cream border-2 border-transparent hover:border-rose-gold focus:border-rose-gold focus:bg-white transition-all duration-300 appearance-none cursor-pointer"
                    >
                      {spaceTypes.map((type) => (
                        <option key={type} value={type}>{type}</option>
                      ))}
                    </select>
                    <svg className="absolute right-4 top-[42px] w-4 h-4 text-rose-gold pointer-events-none" fill="currentColor" viewBox="0 0 20 20">
                      <path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" />
                    </svg>
                  </div>
                </div>

                {/* Results Count */}
                <div className="flex items-center gap-4 pt-6 border-t-2 border-soft-gray">
                  <div className="flex-1">
                    <p className="text-sm text-warm-gray">
